package com.oletvck.gealchprofit;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(GeAlchProfitConfig.GROUP)
public interface GeAlchProfitConfig extends Config
{
	String GROUP = "gealchprofit";

	@ConfigSection(
		name = "Nature runes",
		description = "How the cost of nature runes is factored into profit",
		position = 0
	)
	String natureSection = "natureSection";

	@ConfigItem(
		keyName = "includeNatureCost",
		name = "Subtract nature rune cost",
		description = "Include the cost of one nature rune per cast in the profit calculation.",
		section = natureSection,
		position = 0
	)
	default boolean includeNatureCost()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useLiveNaturePrice",
		name = "Use live nature price",
		description = "Use the current Grand Exchange price of a nature rune. Turn off to use the fixed price below.",
		section = natureSection,
		position = 1
	)
	default boolean useLiveNaturePrice()
	{
		return true;
	}

	@ConfigItem(
		keyName = "natureRunePrice",
		name = "Fixed nature price",
		description = "Nature rune price (gp) used when 'Use live nature price' is off.",
		section = natureSection,
		position = 2
	)
	default int natureRunePrice()
	{
		return 180;
	}

	@ConfigItem(
		keyName = "alchOnlyMode",
		name = "Alch only mode",
		description = "While this is on, the plugin does not track buys on the GE — only items you high alch are tracked. Keeps your flips out of the panel.",
		position = 1
	)
	default boolean alchOnlyMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "trackOnlyProfitable",
		name = "Hide unknown buy price rows",
		description = "Hide items in the panel that have no recorded or manual buy price yet.",
		position = 2
	)
	default boolean trackOnlyProfitable()
	{
		return false;
	}
}

package com.oletvck.gealchprofit;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.FontManager;

/**
 * Side panel that lists every tracked item with its buy price, alch value,
 * nature rune cost, profit per cast and total profit.
 */
class GeAlchProfitPanel extends PluginPanel
{
	private static final Color PROFIT = new Color(0x4C, 0xAF, 0x50);
	private static final Color LOSS = new Color(0xE5, 0x39, 0x35);

	private final GeAlchProfitPlugin plugin;
	private final JPanel sectionsPanel = new JPanel();
	private final JPanel itemsPanel = new JPanel();
	private final JCheckBox alchOnlyCheck = new JCheckBox("Alch only mode");

	GeAlchProfitPanel(GeAlchProfitPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel north = new JPanel();
		north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("Alch Assistant");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		north.add(title);

		alchOnlyCheck.setToolTipText("While this is on, the plugin does not track buys on the GE — only items you high alch. Keeps your flips out of this panel.");
		alchOnlyCheck.setBackground(ColorScheme.DARK_GRAY_COLOR);
		alchOnlyCheck.setForeground(Color.LIGHT_GRAY);
		alchOnlyCheck.setFocusable(false);
		alchOnlyCheck.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		alchOnlyCheck.addActionListener(e -> plugin.setAlchOnlyMode(alchOnlyCheck.isSelected()));
		north.add(alchOnlyCheck);

		sectionsPanel.setLayout(new BoxLayout(sectionsPanel, BoxLayout.Y_AXIS));
		sectionsPanel.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
		sectionsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		north.add(sectionsPanel);

		add(north, BorderLayout.NORTH);

		itemsPanel.setLayout(new BoxLayout(itemsPanel, BoxLayout.Y_AXIS));
		itemsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(itemsPanel, BorderLayout.CENTER);

		final JButton reset = new JButton("Reset all");
		reset.addActionListener(e -> plugin.resetAll());
		final JPanel south = new JPanel(new FlowLayout(FlowLayout.CENTER));
		south.setBackground(ColorScheme.DARK_GRAY_COLOR);
		south.add(reset);
		add(south, BorderLayout.SOUTH);

		rebuild();
	}

	/** Rebuilds the whole panel. Must be called on the EDT. */
	void rebuild()
	{
		sectionsPanel.removeAll();
		itemsPanel.removeAll();

		alchOnlyCheck.setSelected(plugin.alchOnlyMode());

		final List<ItemRecord> recs = plugin.snapshotRecords();

		long grandTotal = 0;
		long totalCasts = 0;
		for (ItemRecord r : recs)
		{
			grandTotal += plugin.totalProfit(r);
			totalCasts += r.getAlchCount();
		}

		// --- Summary box ---
		final JPanel summary = new JPanel(new GridLayout(0, 1, 0, 3));
		summary.setOpaque(false);
		summary.add(summaryRow("Nature rune",
			plugin.includeNatureCost() ? gp(plugin.rawNatureCost()) + " gp" : "ignored",
			Color.LIGHT_GRAY));
		summary.add(summaryRow("Total casts", gp(totalCasts), Color.LIGHT_GRAY));
		summary.add(summaryRow("Total profit", gp(grandTotal) + " gp", colorFor(grandTotal)));
		sectionsPanel.add(section("Summary", summary));

		sectionsPanel.add(Box.createVerticalStrut(8));

		// --- Magic XP box ---
		final int lvl = plugin.magicLevel();
		final JPanel magic = new JPanel(new BorderLayout());
		magic.setOpaque(false);

		final JPanel magicRows = new JPanel(new GridLayout(0, 1, 0, 3));
		magicRows.setOpaque(false);
		magicRows.add(summaryRow("XP gained",
			gp(totalCasts * (long) GeAlchProfitPlugin.HIGH_ALCH_XP), Color.LIGHT_GRAY));
		if (lvl >= 1 && lvl < 99)
		{
			magicRows.add(summaryRow("XP to next", gp(plugin.magicXpToNextLevel()), Color.LIGHT_GRAY));
		}
		magic.add(magicRows, BorderLayout.NORTH);

		if (lvl >= 1)
		{
			final int pct = (int) Math.round(plugin.magicLevelProgress() * 100);
			final JProgressBar bar = new JProgressBar(0, 100);
			bar.setValue(pct);
			bar.setStringPainted(true);
			bar.setForeground(PROFIT);
			bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
			bar.setPreferredSize(new Dimension(10, 20));
			bar.setString(lvl >= 99
				? "Magic 99 (max)"
				: ("Magic " + lvl + " → " + (lvl + 1) + "   " + pct + "%"));

			final JPanel barWrap = new JPanel(new BorderLayout());
			barWrap.setOpaque(false);
			barWrap.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
			barWrap.add(bar, BorderLayout.CENTER);
			magic.add(barWrap, BorderLayout.SOUTH);
		}
		sectionsPanel.add(section("Magic XP", magic));

		boolean any = false;
		for (ItemRecord r : recs)
		{
			if (plugin.hideUnknownBuyPrice() && !r.hasBuyPrice())
			{
				continue;
			}
			// In alch-only mode, hide items that have never been alched (pure flips).
			if (plugin.alchOnlyMode() && r.getAlchCount() == 0)
			{
				continue;
			}
			itemsPanel.add(buildItemCard(r));
			itemsPanel.add(Box.createVerticalStrut(6));
			any = true;
		}

		if (!any)
		{
			final JLabel empty = new JLabel("<html>No items yet.<br>Buy something on the GE and<br>high alch it to start tracking.</html>");
			empty.setForeground(Color.GRAY);
			empty.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
			itemsPanel.add(empty);
		}

		revalidate();
		repaint();
	}

	/** Wraps content in a titled, dark, rounded-look card section. */
	private JPanel section(String title, JPanel content)
	{
		final JPanel box = new JPanel(new BorderLayout());
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createEmptyBorder(8, 10, 10, 10));
		box.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel t = new JLabel(title.toUpperCase());
		t.setForeground(Color.WHITE);
		t.setFont(t.getFont().deriveFont(Font.BOLD, 11f));
		t.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		box.add(t, BorderLayout.NORTH);

		content.setOpaque(false);
		box.add(content, BorderLayout.CENTER);

		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, box.getPreferredSize().height));
		return box;
	}

	private JPanel summaryRow(String label, String value, Color valueColor)
	{
		final JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		final JLabel l = new JLabel(label);
		l.setForeground(Color.GRAY);
		final JLabel v = new JLabel(value);
		v.setForeground(valueColor);
		v.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(l, BorderLayout.WEST);
		row.add(v, BorderLayout.EAST);
		return row;
	}

	private JPanel buildItemCard(ItemRecord r)
	{
		final JPanel card = new JPanel();
		card.setLayout(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 200));

		// Header: name + remove
		final JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		final JLabel name = new JLabel(r.getName().isEmpty() ? ("Item " + r.getItemId()) : r.getName());
		name.setForeground(Color.WHITE);
		name.setFont(FontManager.getRunescapeBoldFont());
		header.add(name, BorderLayout.WEST);

		final JButton remove = new JButton("x");
		remove.setMargin(new java.awt.Insets(0, 4, 0, 4));
		remove.setToolTipText("Stop tracking this item");
		remove.addActionListener(e -> plugin.removeItem(r.getItemId()));
		header.add(remove, BorderLayout.EAST);
		card.add(header, BorderLayout.NORTH);

		// Stats grid
		final JPanel stats = new JPanel(new GridLayout(0, 2, 4, 2));
		stats.setOpaque(false);
		stats.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

		final int buy = r.effectiveUnitBuyPrice();
		final Integer perAlch = plugin.profitPerAlch(r);

		stats.add(stat("Buy", buy < 0 ? "?" : gp(buy) + (r.getManualUnitPrice() >= 0 ? " (set)" : ""), Color.LIGHT_GRAY));
		stats.add(stat("Alch value", gp(r.getHaPrice()), Color.LIGHT_GRAY));
		stats.add(stat("Nature", plugin.includeNatureCost() ? "-" + gp(plugin.rawNatureCost()) : "0", Color.LIGHT_GRAY));
		stats.add(stat("Casts", gp(r.getAlchCount()), Color.LIGHT_GRAY));
		stats.add(stat("Profit / alch", perAlch == null ? "?" : gp(perAlch), perAlch == null ? Color.GRAY : colorFor(perAlch)));
		stats.add(stat("Total", perAlch == null ? "?" : gp(plugin.totalProfit(r)), perAlch == null ? Color.GRAY : colorFor(plugin.totalProfit(r))));
		card.add(stats, BorderLayout.CENTER);

		// Manual buy-price editor
		final JPanel editor = new JPanel(new BorderLayout(4, 0));
		editor.setOpaque(false);
		final JTextField field = new JTextField(r.getManualUnitPrice() >= 0 ? String.valueOf(r.getManualUnitPrice()) : "");
		field.setToolTipText("Set the price you paid per item (overrides the tracked GE average)");
		final JButton set = new JButton("Set buy");
		set.addActionListener(e ->
		{
			final String t = field.getText().replaceAll("[^0-9]", "");
			if (!t.isEmpty())
			{
				plugin.setManualBuyPrice(r.getItemId(), Integer.parseInt(t));
			}
			else
			{
				plugin.clearManualBuyPrice(r.getItemId());
			}
		});
		editor.add(field, BorderLayout.CENTER);
		editor.add(set, BorderLayout.EAST);
		card.add(editor, BorderLayout.SOUTH);

		return card;
	}

	private JPanel stat(String label, String value, Color valueColor)
	{
		final JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		final JLabel l = new JLabel(label);
		l.setForeground(Color.GRAY);
		l.setFont(l.getFont().deriveFont(Font.PLAIN, 10f));
		final JLabel v = new JLabel(value);
		v.setForeground(valueColor);
		v.setFont(v.getFont().deriveFont(Font.BOLD, 11f));
		p.add(l, BorderLayout.NORTH);
		p.add(v, BorderLayout.SOUTH);
		return p;
	}

	private static Color colorFor(long value)
	{
		if (value > 0)
		{
			return PROFIT;
		}
		if (value < 0)
		{
			return LOSS;
		}
		return Color.LIGHT_GRAY;
	}

	private static String gp(long value)
	{
		return String.format("%,d", value);
	}
}

package com.oletvck.gealchprofit;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Alch Assistant",
	description = "Tracks the profit of items bought on the GE and high alched, including nature rune cost.",
	tags = {"alch", "alchemy", "high", "grand", "exchange", "ge", "profit", "money", "nature"}
)
public class GeAlchProfitPlugin extends Plugin
{
	/** Nature rune item id. */
	static final int NATURE_RUNE = 561;

	/** Magic XP granted by a single High Level Alchemy cast. */
	static final int HIGH_ALCH_XP = 65;

	private static final String CONFIG_KEY_RECORDS = "records";
	private static final String ALCH_TARGET = "High Level Alchemy";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GeAlchProfitConfig config;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	/** itemId -> record. Mutated on the client thread, read (snapshotted) on the EDT. */
	private final Map<Integer, ItemRecord> records = new ConcurrentHashMap<>();

	/** GE slot -> last seen snapshot, used to count only the newly-bought delta. */
	private final Map<Integer, SlotSnapshot> slotSnapshots = new HashMap<>();

	/** Item the player most recently aimed High Level Alchemy at, awaiting the cast to complete. */
	private int pendingAlchItemId = -1;
	private int pendingAlchTick = -1;

	/** Last observed total Magic XP, used to detect per-cast XP gains. -1 = unknown. */
	private int lastMagicXp = -1;

	/** Current Magic XP / level, snapshotted on the client thread for the panel. */
	private volatile int currentMagicXp;
	private volatile int currentMagicLevel;

	/** Total XP required to reach each level (index = level, 1..99). */
	private static final int[] XP_TABLE = buildXpTable();

	private static int[] buildXpTable()
	{
		final int[] table = new int[100];
		double points = 0;
		table[1] = 0;
		for (int lvl = 1; lvl < 99; lvl++)
		{
			points += Math.floor(lvl + 300 * Math.pow(2, lvl / 7.0));
			table[lvl + 1] = (int) Math.floor(points / 4);
		}
		return table;
	}

	/** Current nature rune cost, snapshotted on the client thread for the EDT to read. */
	private volatile int natureCostSnapshot;

	private GeAlchProfitPanel panel;
	private NavigationButton navButton;

	@Provides
	GeAlchProfitConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeAlchProfitConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadRecords();

		panel = new GeAlchProfitPanel(this);
		navButton = NavigationButton.builder()
			.tooltip("Alch Assistant")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(this::refreshNatureCost);
		refreshPanel();
	}

	@Override
	protected void shutDown()
	{
		saveRecords();
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		slotSnapshots.clear();
		pendingAlchItemId = -1;
	}

	// ------------------------------------------------------------------
	// Grand Exchange buy tracking
	// ------------------------------------------------------------------

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		// In alch-only mode we ignore GE activity entirely, so flips don't get
		// added to the panel.
		if (config.alchOnlyMode())
		{
			return;
		}

		final int slot = event.getSlot();
		final GrandExchangeOffer offer = event.getOffer();
		final GrandExchangeOfferState state = offer.getState();

		if (state == GrandExchangeOfferState.EMPTY)
		{
			slotSnapshots.remove(slot);
			return;
		}

		// Only buy offers contribute to a buy price.
		final boolean isBuy = state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;

		if (!isBuy)
		{
			slotSnapshots.remove(slot);
			return;
		}

		final int itemId = offer.getItemId();
		final SlotSnapshot prev = slotSnapshots.get(slot);

		// First time we see this slot/offer (e.g. fresh placement, or offers
		// replayed at login): seed the baseline without counting, so we never
		// double-count buys made in a previous session.
		if (prev == null || prev.itemId != itemId)
		{
			slotSnapshots.put(slot, new SlotSnapshot(itemId, offer.getQuantitySold(), offer.getSpent()));
			return;
		}

		final long deltaQty = offer.getQuantitySold() - prev.qtyBought;
		final long deltaSpent = offer.getSpent() - prev.spent;

		if (deltaQty > 0 && deltaSpent >= 0)
		{
			final ItemRecord record = getOrCreate(itemId);
			record.setBuyQty(record.getBuyQty() + deltaQty);
			record.setBuySpent(record.getBuySpent() + deltaSpent);
			saveRecords();
			refreshPanel();
		}

		slotSnapshots.put(slot, new SlotSnapshot(itemId, offer.getQuantitySold(), offer.getSpent()));
	}

	// ------------------------------------------------------------------
	// High alchemy detection
	// ------------------------------------------------------------------

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final String option = event.getMenuOption();
		final String target = event.getMenuTarget();
		if (option == null || !option.equals("Cast")
			|| target == null || !target.contains(ALCH_TARGET))
		{
			return;
		}

		int itemId = event.getItemId();

		// Fallback: spell-on-item entries don't always carry an item id, so read
		// the targeted inventory slot widget directly.
		if (itemId < 0)
		{
			final Widget parent = client.getWidget(event.getParam1());
			final int slot = event.getParam0();
			if (parent != null && slot >= 0)
			{
				final Widget child = parent.getChild(slot);
				if (child != null && child.getItemId() > 0)
				{
					itemId = child.getItemId();
				}
			}
		}

		if (itemId >= 0)
		{
			pendingAlchItemId = itemId;
			pendingAlchTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MAGIC)
		{
			return;
		}

		final int xp = event.getXp();
		final int prev = lastMagicXp;
		lastMagicXp = xp;

		// Each completed High Level Alchemy cast grants Magic XP, firing exactly
		// one StatChanged per cast. Counting these (instead of the cast
		// animation, which does not re-fire for rapid back-to-back casts) means
		// fast alching is captured fully. We attribute the gain to the item the
		// player just clicked the spell on, within a short window.
		//
		// prev < 0 covers the first XP event after launch: the login-time stat
		// load has no pending alch click so it is ignored, but a genuine first
		// cast (pending click set) is still counted.
		final boolean gainedXp = prev < 0 || xp > prev;
		if (gainedXp
			&& pendingAlchItemId >= 0
			&& client.getTickCount() - pendingAlchTick <= 5)
		{
			recordAlch(pendingAlchItemId);
			pendingAlchItemId = -1;
		}
	}

	private void recordAlch(int itemId)
	{
		final ItemRecord record = getOrCreate(itemId);
		record.setAlchCount(record.getAlchCount() + 1);
		record.setHaPrice(highAlchValue(itemId));
		saveRecords();
		refreshPanel();
	}

	// ------------------------------------------------------------------
	// Pricing helpers (call on client thread)
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refreshNatureCost();

		final int xp = client.getSkillExperience(Skill.MAGIC);
		final int lvl = client.getRealSkillLevel(Skill.MAGIC);
		if (xp != currentMagicXp || lvl != currentMagicLevel)
		{
			currentMagicXp = xp;
			currentMagicLevel = lvl;
			refreshPanel();
		}
	}

	private void refreshNatureCost()
	{
		int cost = config.useLiveNaturePrice()
			? itemManager.getItemPrice(NATURE_RUNE)
			: config.natureRunePrice();
		if (cost < 0)
		{
			cost = 0;
		}
		if (cost != natureCostSnapshot)
		{
			natureCostSnapshot = cost;
			refreshPanel();
		}
	}

	private int highAlchValue(int itemId)
	{
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp == null ? 0 : comp.getHaPrice();
	}

	private ItemRecord getOrCreate(int itemId)
	{
		return records.computeIfAbsent(itemId, id ->
		{
			final ItemRecord r = new ItemRecord();
			r.setItemId(id);
			final ItemComposition comp = itemManager.getItemComposition(id);
			if (comp != null)
			{
				r.setName(comp.getName());
				r.setHaPrice(comp.getHaPrice());
			}
			return r;
		});
	}

	// ------------------------------------------------------------------
	// Values consumed by the panel
	// ------------------------------------------------------------------

	/**
	 * The nature rune cost to subtract per cast, honouring the "subtract nature
	 * cost" toggle. Returns 0 when the toggle is off.
	 */
	int effectiveNatureCost()
	{
		return config.includeNatureCost() ? natureCostSnapshot : 0;
	}

	int rawNatureCost()
	{
		return natureCostSnapshot;
	}

	boolean includeNatureCost()
	{
		return config.includeNatureCost();
	}

	boolean hideUnknownBuyPrice()
	{
		return config.trackOnlyProfitable();
	}

	boolean alchOnlyMode()
	{
		return config.alchOnlyMode();
	}

	void setAlchOnlyMode(boolean on)
	{
		configManager.setConfiguration(GeAlchProfitConfig.GROUP, "alchOnlyMode", on);
		refreshPanel();
	}

	int magicLevel()
	{
		return currentMagicLevel;
	}

	int magicXp()
	{
		return currentMagicXp;
	}

	/** XP remaining until the next Magic level. 0 if maxed or not logged in. */
	long magicXpToNextLevel()
	{
		final int lvl = currentMagicLevel;
		if (lvl < 1 || lvl >= 99)
		{
			return 0;
		}
		return (long) XP_TABLE[lvl + 1] - currentMagicXp;
	}

	/** Progress through the current Magic level, 0.0 to 1.0. */
	double magicLevelProgress()
	{
		final int lvl = currentMagicLevel;
		if (lvl >= 99)
		{
			return 1.0;
		}
		if (lvl < 1)
		{
			return 0.0;
		}
		final int base = XP_TABLE[lvl];
		final int next = XP_TABLE[lvl + 1];
		if (next <= base)
		{
			return 0.0;
		}
		final double p = (double) (currentMagicXp - base) / (next - base);
		return Math.max(0.0, Math.min(1.0, p));
	}

	/** Profit per cast for an item, or null if the buy price is unknown. */
	Integer profitPerAlch(ItemRecord record)
	{
		final int buy = record.effectiveUnitBuyPrice();
		if (buy < 0)
		{
			return null;
		}
		return record.getHaPrice() - buy - effectiveNatureCost();
	}

	/** Snapshot of all records for the EDT, sorted by total profit descending. */
	List<ItemRecord> snapshotRecords()
	{
		final List<ItemRecord> copy = new ArrayList<>(records.values());
		copy.sort((a, b) ->
		{
			final long ta = totalProfit(a);
			final long tb = totalProfit(b);
			return Long.compare(tb, ta);
		});
		return copy;
	}

	long totalProfit(ItemRecord record)
	{
		final Integer per = profitPerAlch(record);
		if (per == null)
		{
			return 0;
		}
		return (long) per * record.getAlchCount();
	}

	// ------------------------------------------------------------------
	// Mutations from the panel (marshalled onto the client thread)
	// ------------------------------------------------------------------

	void setManualBuyPrice(int itemId, int price)
	{
		clientThread.invokeLater(() ->
		{
			final ItemRecord record = getOrCreate(itemId);
			record.setManualUnitPrice(Math.max(0, price));
			saveRecords();
			refreshPanel();
		});
	}

	void clearManualBuyPrice(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			final ItemRecord record = records.get(itemId);
			if (record != null)
			{
				record.setManualUnitPrice(-1);
				saveRecords();
				refreshPanel();
			}
		});
	}

	void removeItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			records.remove(itemId);
			saveRecords();
			refreshPanel();
		});
	}

	void resetAll()
	{
		clientThread.invokeLater(() ->
		{
			records.clear();
			slotSnapshots.clear();
			saveRecords();
			refreshPanel();
		});
	}

	// ------------------------------------------------------------------
	// Persistence
	// ------------------------------------------------------------------

	private void refreshPanel()
	{
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}

	private void saveRecords()
	{
		final Collection<ItemRecord> values = records.values();
		final String json = gson.toJson(values);
		configManager.setConfiguration(GeAlchProfitConfig.GROUP, CONFIG_KEY_RECORDS, json);
	}

	private void loadRecords()
	{
		records.clear();
		final String json = configManager.getConfiguration(GeAlchProfitConfig.GROUP, CONFIG_KEY_RECORDS);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			final Type type = new TypeToken<List<ItemRecord>>()
			{
			}.getType();
			final List<ItemRecord> loaded = gson.fromJson(json, type);
			if (loaded != null)
			{
				for (ItemRecord r : loaded)
				{
					records.put(r.getItemId(), r);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load GE Alch Profit records", e);
		}
	}

	/** A small gold-coin style nav icon drawn at runtime (no resource file needed). */
	private static java.awt.image.BufferedImage createIcon()
	{
		final int size = 24;
		final java.awt.image.BufferedImage img =
			new java.awt.image.BufferedImage(size, size, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		final java.awt.Graphics2D g = img.createGraphics();
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new java.awt.Color(0xF4, 0xC4, 0x30));
		g.fillOval(2, 2, size - 4, size - 4);
		g.setColor(new java.awt.Color(0xB8, 0x86, 0x0B));
		g.drawOval(2, 2, size - 5, size - 5);
		g.setColor(new java.awt.Color(0x5A, 0x3E, 0x00));
		g.setFont(new java.awt.Font("SansSerif", java.awt.Font.BOLD, 13));
		final java.awt.FontMetrics fm = g.getFontMetrics();
		final String s = "A";
		g.drawString(s, (size - fm.stringWidth(s)) / 2, (size + fm.getAscent() - fm.getDescent()) / 2);
		g.dispose();
		return img;
	}

	/** Per-slot snapshot used to compute the newly bought delta. */
	private static final class SlotSnapshot
	{
		private final int itemId;
		private final long qtyBought;
		private final long spent;

		private SlotSnapshot(int itemId, long qtyBought, long spent)
		{
			this.itemId = itemId;
			this.qtyBought = qtyBought;
			this.spent = spent;
		}
	}
}

package com.oletvck.gealchprofit;

import lombok.Data;

/**
 * Per-item bookkeeping for buys and high alchemy casts.
 *
 * <p>This class is serialised to JSON (via Gson) and stored in the RuneLite
 * config, so it must remain a simple POJO with no-arg construction.</p>
 */
@Data
public class ItemRecord
{
	/** Item id (canonical, un-noted). */
	private int itemId;

	/** Display name, cached so the panel never has to touch the client thread. */
	private String name = "";

	/** Total quantity bought on the GE since tracking started. */
	private long buyQty;

	/** Total gp spent buying those items on the GE. */
	private long buySpent;

	/** Manual buy-price override per item, or -1 when unset. */
	private int manualUnitPrice = -1;

	/** Number of high alchemy casts recorded for this item. */
	private long alchCount;

	/** Last known high alch value, cached for the panel. */
	private int haPrice;

	/**
	 * The buy price used for profit, in gp per item.
	 *
	 * @return the manual override if set, otherwise the average GE price paid,
	 *         or -1 if no buy price is known yet.
	 */
	public int effectiveUnitBuyPrice()
	{
		if (manualUnitPrice >= 0)
		{
			return manualUnitPrice;
		}
		if (buyQty > 0)
		{
			return (int) Math.round((double) buySpent / buyQty);
		}
		return -1;
	}

	public boolean hasBuyPrice()
	{
		return effectiveUnitBuyPrice() >= 0;
	}
}

